                    if (!overridden)
                        if (auto* dsyn = paramDefaultSyn(ps))
                            if (dsyn->kind ==
                                syntax::SyntaxKind::ParenthesizedExpression)
                                rhsLoc = dsyn->sourceRange();
                    if (!importedFold)
                        setLoc((UHDM::constant*)rhs, rhsLoc);
