                        auto& s9 = stripImplicitConv(e9);
                        if (s9.kind == ExpressionKind::UnaryOp)
                            return s9.as<UnaryExpression>().op ==
                                   UnaryOperator::Minus;
                        if (s9.kind != ExpressionKind::BinaryOp)
                            return false;
