                                        crt9->VpiFullName(cpx9);
                                        crt9->VpiParent(cc9);
                                        auto* cit9 = s.MakeInt_typespec();
                                        if (cs9.as<ParameterSymbol>()
                                                .getType()
                                                .isSigned())
                                            cit9->VpiSigned(true);
                                        crt9->Actual_typespec(cit9);
                                        cit9->VpiParent(crt9);
                                        cc9->Typespec(crt9);
