            cts50->VpiColumnNo(bts50->VpiColumnNo());
            cts50->VpiEndLineNo(bts50->VpiEndLineNo());
            cts50->VpiEndColumnNo(bts50->VpiEndColumnNo());
            cts50->VpiFile(bts50->VpiFile());
